usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Admin.Organization.Projects.RateLimits.ListRateLimits(
		context.TODO(),
		"project_id",
		openai.AdminOrganizationProjectRateLimitListRateLimitsParams{
			Limit: param.NewOpt[int64](100),
			After: param.NewOpt[string]("after"),
			Before: param.NewOpt[string]("before"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
